from z3 import *

s = Solver()
V = [Int(f'v_{i}') for i in range(16)]
for v in V:
    s.add(v >= 0, v <= 36)
s.add(Distinct(V))

edges = []
for g in range(4):
    for i in range(4):
        for j in range(i + 1, 4):
            edges.append((g * 4 + i, g * 4 + j))
for g in range(3):
    for i in range(4):
        edges.append((g * 4 + i, (g + 1) * 4 + i))

edge_labels = []
for idx, (u, v) in enumerate(edges):
    diff = Int(f'e_{idx}')
    s.add(Or(diff == V[u] - V[v], diff == V[v] - V[u]))
    s.add(diff >= 1, diff <= 36)
    edge_labels.append(diff)

s.add(Distinct(edge_labels))

s.set("timeout", 55000)
if s.check() == sat:
    m = s.model()
    print("SAT")
    print([m.evaluate(V[i]).as_long() for i in range(16)])
else:
    print("UNSAT")

from z3 import *

s = Solver()
V = [Int(f'v_{i}') for i in range(16)]
for v in V:
    s.add(v >= 0, v <= 36)
s.add(Distinct(V))

edges = []
for g in range(4):
    for i in range(4):
        for j in range(i + 1, 4):
            edges.append((g * 4 + i, g * 4 + j))
for g in range(3):
    for i in range(4):
        edges.append((g * 4 + i, (g + 1) * 4 + i))

edge_labels = []
for idx, (u, v) in enumerate(edges):
    diff = Int(f'e_{idx}')
    # Use absolute value
    s.add(diff == If(V[u] > V[v], V[u] - V[v], V[v] - V[u]))
    edge_labels.append(diff)

s.add(Distinct(edge_labels))
for e in edge_labels:
    s.add(e >= 1, e <= 36)

s.set("timeout", 55000)
if s.check() == sat:
    m = s.model()
    print("SAT")
    print([m.evaluate(V[i]).as_long() for i in range(16)])
else:
    print("UNSAT")
